#include <vector>
#include <cstddef>
#include <omp.h>

/* Factorize the matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   Store the results for L and U into the original matrix A. 
   A is an NxN matrix stored in row-major.
   Uses in-place Doolittle LU (no pivoting):
   - U is stored on and above the diagonal
   - L is stored below the diagonal with implicit unit diagonal
*/
void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // Outer loop is inherently sequential due to data dependencies between k-steps.
    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // Compute multipliers for L: A[i,k] /= A[k,k], i = k+1..N-1
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Rank-1 update of trailing submatrix:
        // A[i,j] -= A[i,k] * A[k,j], i,j = k+1..N-1
        #pragma omp parallel for collapse(2) schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            for (std::ptrdiff_t j = static_cast<std::ptrdiff_t>(k) + 1; j < static_cast<std::ptrdiff_t>(N); ++j) {
                A[static_cast<size_t>(i) * N + static_cast<size_t>(j)] -=
                    A[static_cast<size_t>(i) * N + k] * A[k * N + static_cast<size_t>(j)];
            }
        }
    }
}
